def handbook(id,title,subtitle,entries,limits):
 return dict(id=id,title=title,subtitle=subtitle,entries=entries,method='מפתח מבואי נבחר, לא חיבור המקיף את כל הדינים. ההסברים ערוכים על פי פירוש המשנה לרמב״ם והמשניות המצוינות בכל סעיף; אינם לשון המחבר. לשון המקורות שמורה לעיון בנפרד.',limits=limits)
final_handbooks=[handbook('moed','שבת ומועדים','מלאכה, שבות ויסודות במצוות המועדים',moed,'נבחרו יסודות במלאכת שבת ויום טוב, בסוכה ובליל פסח. עירובין, תחומין, מוקצה, שאר המועדים ודיני מלאכות פרטיים לא נתבארו כאן. אין זה סדר הלכות למעשה.'),handbook('mammon','דיני ממונות','נזיקין, שומרים, מציאה וקנין ובית דין',mammon,'נבחרו יסודות אחדים בלבד. אין כאן כיסוי של כל אבות הנזק, דיני השומרים, יאוש, דרכי הקנין, הלוואה ורבית, ראיות ושבועות. מטרת הסעיפים להעמיד את החילוקים הראשונים הנצרכים לסוגיה.')]
